amountCents  :   number  ;
billingUrl  :   string  ;
planLabel  ?  :   string  ;
paymentMethodLabel  ?  :   string  ;
invoiceLabel  ?  :   string  ;
}  ;


export     function     paymentFailedEmail  (  {
amountCents  ,   billingUrl  ,   planLabel  ,   paymentMethodLabel  ,   invoiceLabel  ,
}  :     Notice  )     {
if     (  !  Number  .  isSafeInteger  (  amountCents  )     ||   amountCents   <=     0  )     {
throw     new     Error  (  'Expected a positive USD amount in cents'  )  ;
}
