if     (  link  .  protocol     !==     'https:'     ||   link  .  username     ||   link  .  password  )     {
throw     new     Error  (  'Expected a configured HTTPS billing URL'  )  ;
}
const   amount   =     `  USD   ${  (  amountCents   /     100  )  .  toFixed  (  2  )  }  `  ;
const   tree   =     (
<  Email   backgroundColor  =  "#edf1f5"   contentWidth  =  "600px"
