)  ;
const     {   head  ,   body   }     =     renderToHtmlParts  (  tree  )  ;
return     {
subject  :     'Please review your billing details'  ,
html  :     `  <!DOCTYPE html><html><head>  ${  head  }  </head>  ${  body  }  </html>  `  ,
text  :     [
"Your payment didn’t go through."  ,
`  Amount due when this message was prepared:   ${  amount  }  `  ,
planLabel  ,
paymentMethodLabel   &&     `  Payment method:   ${  paymentMethodLabel  }  `  ,
invoiceLabel   &&     `  Invoice:   ${  invoiceLabel  }  `  ,
`  Review billing:   ${  link  .  href  }  `  ,
"If you've already resolved this, your billing page has the latest status."  ,
